import java.io.*;
import java.util.*;

public class Main {
    static int n;
    static long k;
    static long[][] dp; // dp[pos][lastGreater]
    static long LIMIT = (long)1e18;

    static long addLimit(long a, long b) {
        long res = a + b;
        if (res < 0 || res > LIMIT) return LIMIT;
        return res;
    }

    static long solve(int pos, int lastGreater) {
        if (pos == n) return 1;
        if (dp[pos][lastGreater] != -1) return dp[pos][lastGreater];
        long res = 0;
        if (lastGreater == 1) {
            // must be greater than pos
            int cnt = n - pos;
            if (cnt <= 0) return dp[pos][lastGreater] = 0;
            res = cnt;
        } else {
            // lastGreater == 0: can be <= pos or > pos
            int cntLE = pos;      // 1..pos
            int cntGT = n - pos;  // pos+1..n
            res = addLimit(res, cntLE * solve(pos + 1, 0));
            res = addLimit(res, cntGT * solve(pos + 1, 1));
        }
        dp[pos][lastGreater] = res;
        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        k = Long.parseLong(st.nextToken());

        dp = new long[n + 1][2];
        for (int i = 0; i <= n; i++) Arrays.fill(dp[i], -1);

        long total = solve(1, 0);
        if (k > total) k = total; // safety

        int[] p = new int[n + 1];
        boolean[] used = new boolean[n + 1];

        int lastGreater = 0;
        for (int pos = 1; pos <= n; pos++) {
            if (lastGreater == 1) {
                // must pick unused value > pos
                for (int v = pos + 1; v <= n; v++) {
                    if (!used[v]) {
                        long cnt = 1; // dp[pos][1] was just count of choices
                        if (k > cnt) {
                            k -= cnt;
                        } else {
                            p[pos] = v;
                            used[v] = true;
                            lastGreater = 1;
                            break;
                        }
                    }
                }
            } else {
                // lastGreater == 0
                // first consider v <= pos
                for (int v = 1; v <= pos; v++) {
                    if (!used[v]) {
                        long cnt = solve(pos + 1, 0);
                        if (k > cnt) {
                            k -= cnt;
                        } else {
                            p[pos] = v;
                            used[v] = true;
                            lastGreater = 0;
                            break;
                        }
                    }
                }
                if (p[pos] == 0) {
                    // need v > pos
                    for (int v = pos + 1; v <= n; v++) {
                        if (!used[v]) {
                            long cnt = solve(pos + 1, 1);
                            if (k > cnt) {
                                k -= cnt;
                            } else {
                                p[pos] = v;
                                used[v] = true;
                                lastGreater = 1;
                                break;
                            }
                        }
                    }
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= n; i++) {
            if (i > 1) sb.append(' ');
            sb.append(p[i]);
        }
        System.out.println(sb.toString());
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static int n;
    static long k;
    static long[][] dp; // dp[pos][lastGreater]
    static int[] perm;

    static long solveDP(int pos, int lastGreater) {
        if (pos == n) return 1;
        if (dp[pos][lastGreater] != -1) return dp[pos][lastGreater];
        long res = 0;
        int maxVal = (lastGreater == 1) ? pos : n;
        for (int v = pos; v <= maxVal; v++) {
            res += solveDP(pos + 1, v > pos ? 1 : 0);
            if (res > 1000000000000000000L) {
                res = 1000000000000000000L;
                break;
            }
        }
        dp[pos][lastGreater] = res;
        return res;
    }

    static void buildPerm() {
        perm = new int[n + 1];
        int lastGreater = 0;
        for (int pos = 1; pos <= n; pos++) {
            int maxVal = (lastGreater == 1) ? pos : n;
            for (int v = pos; v <= maxVal; v++) {
                long cnt = solveDP(pos + 1, v > pos ? 1 : 0);
                if (cnt >= k) {
                    perm[pos] = v;
                    if (v > pos) lastGreater = 1;
                    break;
                } else {
                    k -= cnt;
                }
            }
        }
    }

    static int[] buildCycles(int[] p) {
        int[] comp = new int[n + 1];
        boolean[] vis = new boolean[n + 1];
        for (int i = 1; i <= n; i++) {
            if (!vis[i]) {
                List<Integer> cyc = new ArrayList<>();
                int cur = i;
                while (!vis[cur]) {
                    vis[cur] = true;
                    cyc.add(cur);
                    cur = p[cur];
                }
                int max = cyc.get(0);
                for (int x : cyc) if (x > max) max = x;
                comp[max] = max;
                for (int x : cyc) {
                    if (x != max) comp[x] = max;
                }
            }
        }
        return comp;
    }

    static boolean checkFixed(int[] p) {
        int[] comp = buildCycles(p);
        int[] q = new int[n + 1];
        int idx = 1;
        for (int i = 1; i <= n; i++) {
            if (comp[i] == i) {
                for (int j = 1; j <= n; j++) {
                    if (comp[j] == i) q[idx++] = j;
                }
            }
        }
        for (int i = 1; i <= n; i++) {
            if (q[i] != p[i]) return false;
        }
        return true;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        k = Long.parseLong(st.nextToken());

        dp = new long[n + 1][2];
        for (int i = 0; i <= n; i++) Arrays.fill(dp[i], -1);

        long total = solveDP(1, 0);
        if (k > total) k = total;

        buildPerm();

        if (!checkFixed(perm)) {
            // Should not happen if DP logic is correct, but just in case
            // fall back to identity
            for (int i = 1; i <= n; i++) perm[i] = i;
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= n; i++) {
            if (i > 1) sb.append(' ');
            sb.append(perm[i]);
        }
        System.out.println(sb.toString());
    }
}

