public class Main {
    static int n;
    static long k;
    static long[][] dp; // dp[pos][last]
    static int[] perm;

    static long solveDP(int pos, int last) {
        if (pos == n) return 1L;
        if (dp[pos][last] != -1) return dp[pos][last];
        long res = 0;
        int start = (last == 0) ? 1 : last;
        for (int v = start; v <= n; v++) {
            res += solveDP(pos + 1, v);
            if (res > 1000000000000000000L) { // cap at 1e18
                res = 1000000000000000000L;
                break;
            }
        }
        dp[pos][last] = res;
        return res;
    }

    static void buildPerm() {
        perm = new int[n];
        int last = 0;
        for (int pos = 0; pos < n; pos++) {
            int start = (last == 0) ? 1 : last;
            for (int v = start; v <= n; v++) {
                long cnt = solveDP(pos + 1, v);
                if (cnt >= k) {
                    perm[pos] = v;
                    last = v;
                    break;
                } else {
                    k -= cnt;
                }
            }
        }
    }

    static List<List<Integer>> getCycles(int[] p) {
        boolean[] vis = new boolean[n + 1];
        List<List<Integer>> cycles = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            if (!vis[i]) {
                List<Integer> cyc = new ArrayList<>();
                int cur = i;
                while (!vis[cur]) {
                    vis[cur] = true;
                    cyc.add(cur);
                    cur = p[cur - 1];
                }
                cycles.add(cyc);
            }
        }
        return cycles;
    }

    static int[] standardRepresentation(int[] p) {
        List<List<Integer>> cycles = getCycles(p);
        List<List<Integer>> stdCycles = new ArrayList<>();
        for (List<Integer> cyc : cycles) {
            int m = cyc.size();
            int maxVal = -1, maxIdx = -1;
            for (int i = 0; i < m; i++) {
                if (cyc.get(i) > maxVal) {
                    maxVal = cyc.get(i);
                    maxIdx = i;
                }
            }
            List<Integer> rotated = new ArrayList<>();
            for (int i = 0; i < m; i++) {
                rotated.add(cyc.get((maxIdx + i) % m));
            }
            stdCycles.add(rotated);
        }
        stdCycles.sort((a, b) -> Integer.compare(a.get(0), b.get(0)));
        int[] res = new int[n];
        int idx = 0;
        for (List<Integer> cyc : stdCycles) {
            for (int v : cyc) {
                res[idx++] = v;
            }
        }
        return res;
    }

    static boolean isFixed(int[] p) {
        int[] s = standardRepresentation(p);
        for (int i = 0; i < n; i++) {
            if (s[i] != p[i]) return false;
        }
        return true;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        k = Long.parseLong(st.nextToken());

        dp = new long[n + 1][n + 1];
        for (int i = 0; i <= n; i++)
            Arrays.fill(dp[i], -1);

        long total = solveDP(0, 0);
        if (k > total) k = total;

        buildPerm();

        // perm is non-decreasing; we must ensure it's fixed under operation.
        // However, by construction using the DP, all such permutations are fixed.
        // Just output perm.
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(' ');
            sb.append(perm[i]);
        }
        System.out.println(sb.toString());
    }
}

