import java.io.*;
import java.util.*;

public class Main {
    static int n;
    static long k;
    static long[][] dp;
    static long LIMIT = (long)1e18;

    static long addLimit(long a, long b) {
        long res = a + b;
        if (res < 0 || res > LIMIT) return LIMIT;
        return res;
    }

    static long mulLimit(long a, long b) {
        if (a == 0 || b == 0) return 0;
        if (a > LIMIT / b) return LIMIT;
        return a * b;
    }

    static long countPerm(int pos) {
        if (pos > n) return 1;
        if (dp[pos][0] != -1) return dp[pos][0];

        long res = 0;
        for (int len = 1; pos + len - 1 <= n; len++) {
            int maxVal = pos + len - 1;
            long ways = 1;
            for (int v = pos; v <= maxVal - 1; v++) {
                ways = mulLimit(ways, maxVal - v);
                if (ways >= LIMIT) break;
            }
            long sub = countPerm(pos + len);
            ways = mulLimit(ways, sub);
            res = addLimit(res, ways);
            if (res >= LIMIT) break;
        }
        dp[pos][0] = res;
        return res;
    }

    static void build(int pos, long k, int[] res) {
        if (pos > n) return;
        for (int len = 1; pos + len - 1 <= n; len++) {
            int maxVal = pos + len - 1;
            long ways = 1;
            for (int v = pos; v <= maxVal - 1; v++) {
                ways = mulLimit(ways, maxVal - v);
                if (ways >= LIMIT) break;
            }
            long sub = countPerm(pos + len);
            long block = mulLimit(ways, sub);
            if (k > block) {
                k -= block;
            } else {
                int[] cycle = new int[len];
                cycle[0] = maxVal;
                List<Integer> remaining = new ArrayList<>();
                for (int v = pos; v <= maxVal - 1; v++) remaining.add(v);

                long curK = (sub == 0 ? 1 : (k - 1) / sub + 1);
                long remK = (sub == 0 ? 1 : (k - 1) % sub + 1);

                for (int i = 1; i < len; i++) {
                    int size = remaining.size();
                    long blockSize = mulLimit(size == 0 ? 1 : 1, 1);
                    for (int j = 0; j < size; j++) {
                        long cnt = countPerm(pos + len);
                        long total = mulLimit(cnt, 1);
                        if (curK > total) {
                            curK -= total;
                        } else {
                            cycle[i] = remaining.get(j);
                            remaining.remove(j);
                            break;
                        }
                    }
                }

                for (int i = 0; i < len; i++) res[pos + i - 1] = cycle[i];
                build(pos + len, remK, res);
                return;
            }
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        k = Long.parseLong(st.nextToken());

        dp = new long[n + 2][1];
        for (int i = 0; i <= n + 1; i++) Arrays.fill(dp[i], -1);

        long total = countPerm(1);
        if (k > total) k = total;

        int[] res = new int[n];
        build(1, k, res);

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(' ');
            sb.append(res[i]);
        }
        System.out.println(sb.toString());
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static int n;
    static long k;
    static long[] dp; // dp[i] = number of valid permutations of length i
    static long LIMIT = (long)1e18;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        k = Long.parseLong(st.nextToken());

        dp = new long[n + 1];
        computeDP();

        int[] perm = buildPermutation(n, k);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(' ');
            sb.append(perm[i]);
        }
        System.out.println(sb.toString());
    }

    // dp recurrence:
    // dp[0] = 1
    // dp[1] = 1
    // dp[i] = dp[i-1] + (i-1)*dp[i-2]  (clamped to LIMIT)
    static void computeDP() {
        dp[0] = 1;
        if (n >= 1) dp[1] = 1;
        for (int i = 2; i <= n; i++) {
            long val = dp[i - 1] + (long)(i - 1) * dp[i - 2];
            if (val > LIMIT) val = LIMIT;
            dp[i] = val;
        }
    }

    // Build k-th permutation in lexicographic order among permutations
    // whose standard cyclic representation concatenation equals the permutation.
    static int[] buildPermutation(int len, long k) {
        int[] res = new int[len];
        int pos = 0;
        int cur = 1; // next smallest unused number
        while (pos < len) {
            int remaining = len - pos;
            // Option 1: singleton cycle at position pos
            long countSingleton = dp[remaining - 1];
            if (countSingleton >= k) {
                res[pos] = cur;
                pos++;
                cur++;
            } else {
                k -= countSingleton;
                // Option 2: cycle of length L >= 2 starting at pos
                boolean done = false;
                for (int L = 2; L <= remaining; L++) {
                    long countForL = dp[remaining - L];
                    long totalForL = countForL * (L - 1);
                    if (totalForL >= k) {
                        // choose which of the next L-1 numbers is second in cycle
                        int idx = (int)((k - 1) / countForL); // 0-based
                        int secondVal = cur + 1 + idx;
                        // cycle is [cur, secondVal, ...], but in concatenation
                        // we place cur, then secondVal, then the rest of cycle
                        // which are the remaining numbers in this block in increasing order
                        res[pos] = cur;
                        res[pos + 1] = secondVal;
                        int write = pos + 2;
                        for (int v = cur + 1; v <= cur + L - 1; v++) {
                            if (v == secondVal) continue;
                            res[write++] = v;
                        }
                        pos += L;
                        cur += L;
                        k = (k - 1) % countForL + 1;
                        done = true;
                        break;
                    } else {
                        k -= totalForL;
                    }
                }
                if (!done) {
                    // should not happen if k is valid
                    break;
                }
            }
        }
        return res;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static long[][] C = new long[51][51];
    static long[] fact = new long[51];

    static void precompute() {
        for (int i = 0; i <= 50; i++) {
            C[i][0] = C[i][i] = 1;
            for (int j = 1; j < i; j++) {
                C[i][j] = Math.min(1000000000000000000L, C[i - 1][j - 1] + C[i - 1][j]);
            }
        }
        fact[0] = 1;
        for (int i = 1; i <= 50; i++) {
            fact[i] = Math.min(1000000000000000000L, fact[i - 1] * i);
        }
    }

    static long countPerm(int n) {
        long res = 0;
        for (int m = 0; m <= n; m++) {
            long add = C[n][m] * fact[m];
            if (add > 1000000000000000000L) add = 1000000000000000000L;
            res += add;
            if (res > 1000000000000000000L) return 1000000000000000000L;
        }
        return res;
    }

    static long countWithPrefix(int n, int pos, int[] perm, boolean[] used) {
        int fixed = 0;
        for (int i = 1; i <= pos; i++) if (perm[i] == i) fixed++;
        int remaining = n - pos;
        long res = 0;
        for (int m = 0; m <= remaining; m++) {
            long waysChooseFixed = C[remaining][m];
            long waysPerm = fact[m + fixed];
            long add = waysChooseFixed * waysPerm;
            if (add > 1000000000000000000L) add = 1000000000000000000L;
            res += add;
            if (res > 1000000000000000000L) return 1000000000000000000L;
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        precompute();
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        long k = Long.parseLong(st.nextToken());

        int[] perm = new int[n + 1];
        boolean[] used = new boolean[n + 1];

        for (int pos = 1; pos <= n; pos++) {
            for (int v = 1; v <= n; v++) {
                if (used[v]) continue;
                perm[pos] = v;
                used[v] = true;
                long cnt = countWithPrefix(n, pos, perm, used);
                if (cnt >= k) {
                    break;
                } else {
                    k -= cnt;
                    used[v] = false;
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= n; i++) {
            if (i > 1) sb.append(' ');
            sb.append(perm[i]);
        }
        System.out.println(sb.toString());
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static int n;
    static long k;
    static long[][] dp; // dp[pos][lastGreater]
    static long LIMIT = (long)1e18;

    static long addLimit(long a, long b) {
        long res = a + b;
        if (res < 0 || res > LIMIT) return LIMIT;
        return res;
    }

    static void buildDP() {
        dp = new long[n + 2][n + 2];
        dp[n + 1][0] = 1;
        for (int pos = n; pos >= 1; pos--) {
            for (int lg = 0; lg <= n; lg++) {
                long val = 0;
                // choose fixed point
                val = addLimit(val, dp[pos + 1][lg]);
                // choose start of new cycle
                int newLg = lg + 1;
                if (newLg <= n) {
                    val = addLimit(val, dp[pos + 1][newLg]);
                }
                dp[pos][lg] = val;
            }
        }
    }

    static int[] solve() {
        int[] perm = new int[n + 1]; // 1-based
        int pos = 1;
        int lastGreater = 0;
        long remaining = k;

        while (pos <= n) {
            // option 1: fixed point
            long cntFixed = dp[pos + 1][lastGreater];
            if (cntFixed >= remaining) {
                perm[pos] = pos;
                pos++;
                continue;
            }
            remaining -= cntFixed;

            // option 2: start of new cycle
            lastGreater++;
            perm[pos] = pos; // temporarily, will adjust when closing cycle
            // we need to build the cycle starting at pos
            int start = pos;
            int cur = pos;
            List<Integer> cyclePositions = new ArrayList<>();
            cyclePositions.add(cur);

            while (true) {
                if (cur == n) {
                    // must close cycle to start
                    perm[cur] = start;
                    pos = n + 1;
                    break;
                }
                // decide next position in cycle
                // option A: close cycle now
                long cntClose = dp[cur + 1][lastGreater];
                if (cntClose >= remaining) {
                    perm[cur] = start;
                    pos = cur + 1;
                    break;
                }
                remaining -= cntClose;

                // option B: extend cycle to some next position > cur
                int nextPos = -1;
                for (int candidate = cur + 1; candidate <= n; candidate++) {
                    long cnt = dp[candidate + 1][lastGreater];
                    if (cnt >= remaining) {
                        nextPos = candidate;
                        break;
                    }
                    remaining -= cnt;
                }
                if (nextPos == -1) nextPos = cur + 1;
                perm[cur] = nextPos;
                cur = nextPos;
                cyclePositions.add(cur);
            }
        }
        return perm;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        k = Long.parseLong(st.nextToken());

        buildDP();
        int[] ans = solve();
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= n; i++) {
            if (i > 1) sb.append(' ');
            sb.append(ans[i]);
        }
        System.out.println(sb.toString());
    }
